import{_ as t,o as a,c as o,a3 as s}from"./chunks/framework.DAK02U1-.js";const g=JSON.parse('{"title":"How xclang Is Tested","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"How xclang Is Tested | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/dev/testing"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/dev/testing"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/dev/testing"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/dev/testing"}]]},"headers":[],"relativePath":"xclang/dev/testing.md","filePath":"en/xclang/dev/testing.md","lastUpdated":1791304688000}'),d={name:"xclang/dev/testing.md"};function n(c,e,i,r,l,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="how-xclang-is-tested" tabindex="-1">How xclang Is Tested <a class="header-anchor" href="#how-xclang-is-tested" aria-label="Permalink to &quot;How xclang Is Tested&quot;">​</a></h1><p>Every claim the docs make about what xclang does is checked by a test that runs on CI, on GitHub-hosted runners of every host. This page maps the claims to the tests and the workflows that run them. The other pages link here instead of naming tests.</p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><ul><li>Before a release, each host archive is tested on a machine of that host (<code>tests/smoke.ts</code>, <code>tests/libclang.ts</code>). The CMake package and the Bazel module are tested with the archives (<code>tests/cmake.ts</code>, <code>tests/bazel</code>), and so are the MSVC targets and the macOS targets from Linux and Windows hosts (<code>tests/msvc.ts</code>, <code>tests/macos.ts</code>). The <code>xclang</code> command is tested on every host (<code>tests/cli.ts</code>).</li><li>On publishing, the Bazel module is checked further (<code>tests/bazel.ts</code>), and cross-built programs run on a machine of their target, with no emulator: 22 host-to-target pairs.</li><li>After a release is published, examples.yml runs the commands of the docs as written, from conda.clice.io, the archives, the tag and bazel.clice.io. What they build for another target then runs on a runner of that target.</li><li><code>tests/docs.ts</code> checks that the files the docs show are the files CI builds, that their commands are the steps examples.yml runs, and that every link reaches its page and heading.</li></ul><h2 id="when-tests-run" tabindex="-1">When Tests Run <a class="header-anchor" href="#when-tests-run" aria-label="Permalink to &quot;When Tests Run&quot;">​</a></h2><table tabindex="0"><thead><tr><th>workflow</th><th>when</th><th>what</th></tr></thead><tbody><tr><td>main.yml, stage <code>package</code> (package.yml)</td><td>every release candidate</td><td>each host&#39;s archives made again on another machine, in another directory, with other file times, umask 077 and three xz threads (the first has four): the same bytes</td></tr><tr><td>main.yml, stage <code>test</code> (test.yml)</td><td>every release candidate</td><td><code>tests/smoke.ts</code> and <code>tests/libclang.ts</code> on a machine of each host</td></tr><tr><td>bazel.yml</td><td>every release candidate</td><td><code>tests/bazel</code> with the module</td></tr><tr><td>bazel.yml</td><td>on publishing, and by hand</td><td>also <code>tests/bazel.ts</code>, and cross builds run on the target (<code>tests/bazel-cross.ts</code>)</td></tr><tr><td>cmake.yml</td><td>every release candidate, and on publishing</td><td><code>tests/cmake.ts</code>: the package by <code>PATH</code>, through the toolchain file, and from FetchContent of the tag</td></tr><tr><td>conda.yml</td><td>before the conda packages are published</td><td>each package installed with pixi and used, on every host</td></tr><tr><td>examples.yml</td><td>after publishing, and on pushes that change <code>examples/</code> or the workflow</td><td>the commands and <code>examples/</code> of the docs, as written; the programs for other targets on their runners</td></tr><tr><td>docs.yml</td><td>pushes that change the docs, <code>examples/</code>, <code>tests/docs.ts</code> or a workflow, on every branch</td><td><code>tests/docs.ts</code>; on <code>main</code>, then publishing to docs.clice.io</td></tr><tr><td>cli.yml</td><td>every release candidate, with main.yml&#39;s <code>cli</code> (on by default), and by hand</td><td>the <code>xclang</code> command: <code>tests/cli.ts</code>, <code>tests/cargo.ts</code></td></tr><tr><td>main.yml, stage <code>msvc</code> (msvc.yml)</td><td>every release candidate; needs <code>cli</code>, as the archives&#39; <code>xclang</code> fetches the SDK</td><td>the MSVC targets: <code>tests/msvc.ts</code></td></tr><tr><td>main.yml, stage <code>macos</code> (macos.yml)</td><td>every release candidate; needs <code>cli</code></td><td>the macOS targets from Linux and Windows hosts: <code>tests/macos.ts</code></td></tr><tr><td>bench.yml</td><td>by hand, for the notes or the docs</td><td>compile speed against LLVM&#39;s and Apple&#39;s builds (<code>tests/bench.ts</code>)</td></tr></tbody></table><p>How the stages fit together is in the <a href="./release-build">build pipeline</a>.</p><h2 id="the-toolchain-on-each-host" tabindex="-1">The Toolchain on Each Host <a class="header-anchor" href="#the-toolchain-on-each-host" aria-label="Permalink to &quot;The Toolchain on Each Host&quot;">​</a></h2><p><code>tests/smoke.ts</code> checks an unpacked toolchain on a machine of its host:</p><ul><li>Its own programs load no C++ runtime, and on Linux need glibc 2.17 at most.</li><li>C and C++ programs (exceptions, iostreams, threads) build for every target the host can build for, and run where the machine can run them. That includes x86_64 macOS programs on arm64 macOS through Rosetta, and x86_64 Windows programs on Windows on Arm.</li><li>Natively: <code>import std</code>, a precompiled header, ThinLTO, wide atomics, hardening flags (<code>_LIBCPP_HARDENING_MODE_DEBUG</code>), a version resource, and <code>-static</code> on Linux.</li><li>The <a href="./../design/hermeticity#gcc-library-names">GCC library names</a> link: <code>-latomic</code>, <code>-lgcc</code>, <code>-lgcc_eh</code>, <code>-lgcc_s</code>, <code>-lssp</code> on Windows, <code>-lstdc++</code>, and <code>windres</code>.</li><li>The checks each <a href="./../reference/patches">LLVM patch</a> was made against. For example, <code>--no-default-config --target=&lt;arch&gt;-pc-windows-msvc</code> finds Visual Studio on the Windows runners (patch 0004).</li><li>The MSVC targets: their compiler-rt is there, and without a fetched SDK clang and a plain clang-cl stop and name <code>sdk/windows</code>.</li><li>ASan, TSan and libFuzzer on Linux and macOS hosts. An overflow within the capacity of a <code>std::string</code> is reported, and a program that shares the <code>std::filesystem</code> instantiations of <code>libc++.a</code> gets no false report (<a href="./../features/sanitizers#why-an-asan-libc">why an ASan libc++</a>).</li><li>dSYM and GSYM debug symbols made by the toolchain&#39;s <code>dsymutil</code> and <code>llvm-gsymutil</code>, for every target.</li></ul><p><code>tests/libclang.ts</code> builds and runs <code>tests/libclang</code>, a small tool on libclang. It finds libclang through <code>find_package(Clang)</code>, links the ThinLTO bitcode, and registers every target&#39;s MC layer.</p><h2 id="programs-and-what-they-load" tabindex="-1">Programs and What They Load <a class="header-anchor" href="#programs-and-what-they-load" aria-label="Permalink to &quot;Programs and What They Load&quot;">​</a></h2><p>examples.yml builds the <a href="./../guide/quick-start">quick start</a> programs for every target on every host, and lists what each loads with <code>llvm-readobj --needed-libs</code>. Linux programs load <code>libc.so.6</code>, <code>libm.so.6</code>, <code>libdl.so.2</code>, <code>libpthread.so.0</code> and the dynamic loader. Windows programs load <code>KERNEL32.dll</code> and UCRT. macOS programs load <code>libSystem.B.dylib</code>. The job fails if any program loads a C++ runtime. That is the <a href="./../design/hermeticity">hermeticity</a> rule, checked.</p><h2 id="cross-compiling" tabindex="-1">Cross-Compiling <a class="header-anchor" href="#cross-compiling" aria-label="Permalink to &quot;Cross-Compiling&quot;">​</a></h2><ul><li><code>tests/smoke.ts</code> and <code>tests/cmake.ts</code> build for every target on every host.</li><li>bazel.yml builds <code>tests/bazel</code> on every host for every other target it can build for: 22 host-to-target pairs. A machine of the target then runs the tests (<code>tests/bazel-cross.ts</code>): Linux-built Windows programs on Windows, Windows-built Linux programs on Linux, and so on.</li><li>From Linux x64, bazel.yml builds kotatsu&#39;s tests, from the registry, for Windows x64, and runs them on Windows.</li><li>examples.yml builds the programs of the docs for other targets, with clang, CMake, FetchContent, Meson, Make, Bazel and cargo, and uploads them. Its <code>on-target</code> job runs each on a runner of its target, with nothing installed, and compares what it prints with the <code>expected.txt</code> of its example. That covers every host to every Linux and Windows target, and both macOS targets from both macOS hosts. Its <code>sdk</code> job fetches the vendor SDKs with the release&#39;s <code>xclang</code> on Linux x64, Windows x64 and macOS arm64, as the docs show, and builds for both MSVC targets (clang, clang-cl, CMake, cargo) and, on Linux and Windows, for both macOS targets (clang, CMake, cargo); <code>on-target</code> runs those programs on Windows x64 and arm64 and on Macs too. Nothing of an SDK leaves the job.</li></ul><h2 id="cmake-package" tabindex="-1">CMake Package <a class="header-anchor" href="#cmake-package" aria-label="Permalink to &quot;CMake Package&quot;">​</a></h2><p><code>tests/cmake.ts</code> builds <code>tests/cmake</code> on every host, with CMake 3.28 and Ninja 1.11, and with the newest of both:</p><ol><li><code>find_package(xclang)</code> found by <code>PATH</code>, with <code>CMAKE_CXX_COMPILER=clang++</code>.</li><li>Every other target the host builds for, through the toolchain file and <code>XCLANG_TARGET</code>. The programs run where the machine can run them.</li><li>Nothing installed: FetchContent of the tag, whose <code>xclang.cmake</code> downloads <code>SHA256SUMS</code> and the host toolchain.</li><li><code>tests/libclang</code> with the ThinLTO cache. A second link takes every module&#39;s code from the cache, and the program is the same.</li></ol><p><code>tests/cmake</code> covers a C++ module of partitions, <code>xclang::std</code> with <code>std.compat</code>, <code>xclang_add_std</code> with <code>-fno-exceptions</code>, and <code>xclang_debug_symbols</code>.</p><h2 id="bazel-module" tabindex="-1">Bazel Module <a class="header-anchor" href="#bazel-module" aria-label="Permalink to &quot;Bazel Module&quot;">​</a></h2><p><code>tests/bazel</code> builds and tests with the module on every host. <code>tests/bazel.ts</code> then checks, with the same disk cache:</p><ol><li><strong>No absolute paths.</strong> A copy of the checkout elsewhere, with another output base, builds the programs from the disk cache alone. So do they built for a target of another OS, which fetches no other host toolchain and only that target&#39;s libclang. A macOS target off macOS fails and says why.</li><li><strong>The registry archive.</strong> The module as <code>scripts/bazel.ts</code> packs it for bazel.clice.io gives the same actions, from the disk cache.</li><li><strong><code>git_override</code></strong> of a commit, with <code>strip_prefix = &quot;packages/bazel&quot;</code>, builds the programs.</li><li><strong>A new release rebuilds.</strong> The copy at the previous release runs every compile and link again.</li><li><strong><code>gc_sections</code></strong>: on by default for Linux in optimized links, off for Windows unless asked for.</li><li><strong>The cost of declared inputs</strong>: the programs built in the sandbox and outside it, one action at a time, on Linux and macOS.</li><li><strong>The ThinLTO cache</strong> on the link of libclang&#39;s bitcode: the module makes the directory, again once it is gone. A second link takes every module&#39;s code from it, and the program is the same without it.</li><li><strong>Debug symbols</strong> by <code>xclang_debug_symbols</code>: GSYM, and dSYM on macOS, with lines of the program&#39;s code and of libclang after ThinLTO, for another OS&#39;s target too.</li><li><strong>Debug information wherever the build ran.</strong> A <code>-c dbg</code> program is the same bytes from another checkout, and so is the DWARF of its dSYM on macOS. gdb (Linux), lldb with and without a dSYM (macOS) and llvm-symbolizer (Linux, Windows) find a source in the workspace and one in an external repository.</li><li><strong>Strip</strong> by object format, for the host target and another OS&#39;s.</li><li><strong><code>@libclang</code> follows <code>--features=asan</code></strong>: its libraries and resource directory switch together.</li></ol><p>examples.yml builds <code>examples/bazel</code> from bazel.clice.io on every host, and for another target.</p><h2 id="c-20-modules" tabindex="-1">C++20 Modules <a class="header-anchor" href="#c-20-modules" aria-label="Permalink to &quot;C++20 Modules&quot;">​</a></h2><ul><li><code>tests/cmake</code> builds a module of partitions and <code>import std</code> on every host, for every target, with CMake 3.28 and the newest.</li><li><code>tests/bazel</code> builds a module of partitions, a module importing another, a module unit reading the defines of a library it depends on, and <code>import std</code>, on every host and for every other target.</li><li>examples.yml builds <code>examples/modules</code>, a module with a partition and <code>import std</code>, by hand with one-step compiles, with CMake and with Bazel, on every host, and for Windows x64 with CMake and Bazel.</li><li>examples.yml&#39;s <code>ccache</code> job runs the command lines CMake gives a module and its importer three times, under ccache 4.13.6 and 4.14.1. The job fails when either version stops behaving as <a href="./../features/modules#build-caches-and-modules">build caches and modules</a> says.</li></ul><h2 id="the-xclang-command" tabindex="-1">The xclang Command <a class="header-anchor" href="#the-xclang-command" aria-label="Permalink to &quot;The xclang Command&quot;">​</a></h2><p>cli.yml builds the <code>xclang</code> command for every host, with a released xclang as the C compiler and linker (<code>scripts/cli.ts</code>). On a machine of each host, <code>tests/cli.ts</code> then:</p><ul><li>fetches both vendor SDKs;</li><li>cross-compiles C, C++ and Objective-C programs against them, for both macOS architectures and for x64 and arm64 Windows (MSVC ABI), and runs them on macOS and Windows runners;</li><li>adds and removes targets against a test index.</li></ul><p>From Linux, <code>tests/cargo.ts</code> builds <code>cli/</code> with cargo for macOS and the MSVC ABI against the fetched SDKs (<a href="./../integrations/cargo">Rust and Cargo</a>).</p><h2 id="msvc-targets" tabindex="-1">MSVC Targets <a class="header-anchor" href="#msvc-targets" aria-label="Permalink to &quot;MSVC Targets&quot;">​</a></h2><p>msvc.yml tests the MSVC targets with a run&#39;s archives, from Linux x64, macOS arm64 and Windows x64 hosts. On each, <code>tests/msvc.ts</code>:</p><ul><li>checks that clang and clang-cl stop without the SDK and name <code>sdk/windows</code>;</li><li>fetches the SDK of <code>windows-latest</code> with the archive&#39;s <code>xclang</code>, and windows-2022&#39;s for x64, and switches between them with <code>sdk use</code>;</li><li>builds, for x64 and arm64, C and C++ (exceptions, threads, <code>&lt;filesystem&gt;</code>, <code>&lt;format&gt;</code>) with clang, clang++ and clang-cl, <code>__int128</code> division, a Win32 program, ThinLTO, debug information, UBSan, the profile runtime, and for x64 ASan with the static and the DLL CRT and libFuzzer;</li><li>checks the DLLs each program imports: the hybrid CRT imports UCRT&#39;s API sets and no <code>vcruntime140.dll</code> or <code>msvcp140.dll</code>; <code>/MD</code> and <code>-fms-runtime-lib=dll</code> import both; all-static, <code>/MTd</code> and <code>-fms-runtime-lib=static_dbg</code> import neither; none imports a debug DLL;</li><li>builds <code>tests/cmake</code> for both targets through the toolchain file, and from Linux kotatsu and its tests for x64.</li></ul><p>The programs of every host then run on windows-2025 and windows-11-arm, and kotatsu&#39;s tests in its source tree. Only programs leave a job, never anything of the SDK.</p><h2 id="macos-from-linux-and-windows" tabindex="-1">macOS from Linux and Windows <a class="header-anchor" href="#macos-from-linux-and-windows" aria-label="Permalink to &quot;macOS from Linux and Windows&quot;">​</a></h2><p>macos.yml tests the macOS targets from Linux and Windows hosts with a run&#39;s archives, on Linux x64 and arm64 and Windows x64 and arm64 hosts. On each, <code>tests/macos.ts</code>:</p><ul><li>checks that clang without the SDK names <code>sdk/macos</code>, and that the CMake package stops and says how to fetch it;</li><li>fetches the SDK of <code>macos-latest</code> with the archive&#39;s <code>xclang</code>, and checks that an <code>-isysroot</code> of the command line replaces <code>sdk/macos</code>;</li><li>builds, for arm64 and x86_64, with a bare <code>--target</code>: C, C++ (exceptions, threads, <code>&lt;filesystem&gt;</code>, <code>&lt;format&gt;</code>), <code>import std</code>, ThinLTO, debug information in a dSYM, with ThinLTO too, CoreFoundation, Objective-C with Foundation, a dylib and a program that <code>llvm-install-name-tool</code> gives an rpath, UBSan, ASan, TSan, libFuzzer and the profile runtime;</li><li>checks with <code>llvm-otool</code> that each program loads <code>libSystem</code> and only what else it uses (its frameworks, <code>libobjc</code>, xclang&#39;s sanitizer runtimes, its dylib), never <code>libc++.dylib</code>, and that it names macOS 13.0 and the fetched SDK&#39;s version;</li><li>builds <code>tests/cmake</code> for both targets through the toolchain file, and reads its GSYM, made from the dSYM;</li><li>makes universal programs of both with <code>llvm-lipo</code>.</li></ul><p>The programs of every host then run on macos-15 (arm64) and macos-15-intel, with the sanitizers&#39; dylibs next to them. On arm64 each is checked for the linker&#39;s ad-hoc signature, with no <code>codesign</code> run; Apple&#39;s <code>dwarfdump</code> and <code>atos</code> read the dSYMs. Only programs leave a job, with their dSYMs, never anything of the SDK.</p><h2 id="the-feature-examples" tabindex="-1">The Feature Examples <a class="header-anchor" href="#the-feature-examples" aria-label="Permalink to &quot;The Feature Examples&quot;">​</a></h2><p>examples.yml builds the example of each feature page, in <code>examples/</code>, and checks what the page says it prints:</p><ul><li><strong>Sanitizers</strong>, on Linux and macOS hosts: by hand, with CMake and with Bazel. ASan with the ASan libc++ reports the container-overflow and exits 1; without it, no report. TSan reports the data race and exits 66. On macOS, both abort after the report. libFuzzer runs 1000 inputs.</li><li><strong>Debug symbols</strong>, on every host: a GSYM by hand, looked up by the address of a function, and with <code>xclang_debug_symbols</code> in CMake (with the dSYM on macOS) and in Bazel.</li><li><strong>libclang and the ThinLTO cache</strong>, on every host: the tool on the release archive of libclang with CMake, and on <code>@libclang</code> with Bazel. The job records the link times and the entries of the cache.</li><li><strong>Cargo</strong>, from Linux x64 and macOS arm64: Rust programs with C code for Windows x64 and arm64 and for Linux arm64, run on their targets. The Windows programs load no runtime DLL.</li></ul><h2 id="the-docs" tabindex="-1">The Docs <a class="header-anchor" href="#the-docs" aria-label="Permalink to &quot;The Docs&quot;">​</a></h2><ul><li><code>node tests/docs.ts</code> checks that every code block under a <code>&lt;!-- file: --&gt;</code> marker is that file of the repository, and every block under <code>&lt;!-- excerpt: --&gt;</code> consecutive lines of its file. Each command block outside these Development pages is a step of examples.yml, or says why CI does not run it (<code>&lt;!-- not run: --&gt;</code>). It also checks that every directory of <code>examples/</code> is built and shown, that every relative link reaches its page and heading, and that the status of every unshipped item is one of the <a href="./../design/roadmap">roadmap</a> words.</li><li>examples.yml runs the commands of the docs and <code>examples/</code> on every host, against the published release. Make runs on Linux and macOS hosts. Windows hosts also build the CMake and Meson projects for <code>aarch64-unknown-linux-gnu</code>.</li></ul><h2 id="checked-by-hand" tabindex="-1">Checked by Hand <a class="header-anchor" href="#checked-by-hand" aria-label="Permalink to &quot;Checked by Hand&quot;">​</a></h2><p>Some claims were checked once, by hand, and are not part of a workflow:</p><ul><li>The dSYM and the program came out the same bytes with and without the ThinLTO cache, cold or warm, for 23.1.2.6 on arm64 and x86_64 macOS (<a href="./../features/debugging#why-a-dsym-comes-from-the-link">debugging</a>).</li><li>llvm-gsymutil wrote three different files in three runs on one program, and the same file every run with <code>--num-threads=1</code> (<a href="./../features/debugging#known-limitations">debugging</a>).</li><li>lld linked clice&#39;s 600 MB <code>clice.exe</code> with ThinLTO six times from the same inputs, in three layouts (<a href="./../design/windows#known-limitations">Windows</a>).</li></ul><h2 id="speed" tabindex="-1">Speed <a class="header-anchor" href="#speed" aria-label="Permalink to &quot;Speed&quot;">​</a></h2><p>bench.yml compares the compile speed of a release with LLVM&#39;s own build of the same version, and with Apple&#39;s clang on macOS. The method and the numbers are in <a href="./../design/pgo#what-it-buys">PGO</a>.</p><h2 id="runs-for-23-1-2-7" tabindex="-1">Runs for 23.1.2.7 <a class="header-anchor" href="#runs-for-23-1-2-7" aria-label="Permalink to &quot;Runs for 23.1.2.7&quot;">​</a></h2><table tabindex="0"><thead><tr><th>workflow</th><th>run</th></tr></thead><tbody><tr><td>main.yml (build, <code>test</code>, <code>bazel</code>, <code>cmake</code>, <code>msvc</code> and <code>macos</code> stages)</td><td><a href="https://github.com/clice-io/xclang/actions/runs/37454002667" target="_blank" rel="noreferrer">37454002667</a></td></tr><tr><td>bazel.yml, on publishing</td><td><a href="https://github.com/clice-io/xclang/actions/runs/37481563479" target="_blank" rel="noreferrer">37481563479</a></td></tr><tr><td>cmake.yml, on publishing</td><td><a href="https://github.com/clice-io/xclang/actions/runs/37481563519" target="_blank" rel="noreferrer">37481563519</a></td></tr><tr><td>conda.yml</td><td><a href="https://github.com/clice-io/xclang/actions/runs/37481672889" target="_blank" rel="noreferrer">37481672889</a></td></tr><tr><td>examples.yml</td><td><a href="https://github.com/clice-io/xclang/actions/runs/37494316755" target="_blank" rel="noreferrer">37494316755</a></td></tr><tr><td>bench.yml</td><td>23.1.2.6&#39;s: <a href="https://github.com/clice-io/xclang/actions/runs/37356476645" target="_blank" rel="noreferrer">37356476645</a></td></tr></tbody></table>',49)])])}const u=t(d,[["render",n]]);export{g as __pageData,u as default};
